713	// squashTouchesStagedPath reports whether a staged path is one that a
714	// commit Git recorded in SQUASH_MSG changed. Git leaves SQUASH_MSG behind when a
715	// squash is abandoned, so the file alone is not proof that the current staged
716	// work belongs to those commits; matching paths rather than content keeps a
717	// squash whose files were touched up before committing.
718	func squashTouchesStagedPath(ctx context.Context, repo *git.Repository, squashMsg []byte) bool {
719		files, err := getStagedFiles(ctx)
720		if err != nil || len(files) == 0 {
721			return false
722		}
723		staged := make(map[string]bool, len(files))
724		for _, f := range files {
725			staged[f] = true
726		}
727		for _, line := range strings.Split(string(squashMsg), "\n") {
728			fields := strings.Fields(line)
729			if len(fields) != 2 || fields[0] != "commit" || !plumbing.IsHash(fields[1]) {
730				continue
731			}
732			commit, err := repo.CommitObject(plumbing.NewHash(fields[1]))
733			if err != nil {
734				continue
735			}
736			if commitChangesAnyPath(commit, staged) {
737				return true
738			}
739		}
740		return false
741	}
