743	// commitChangesAnyPath reports whether c changed one of wanted relative to its
744	// first parent (or added it, for a root commit).
745	func commitChangesAnyPath(c *object.Commit, wanted map[string]bool) bool {
746		tree, err := c.Tree()
747		if err != nil {
748			return false
749		}
750		var parentTree *object.Tree
751		if parent, err := c.Parents().Next(); err == nil {
752			if parentTree, err = parent.Tree(); err != nil {
753				return false
754			}
755		}
756		changes, err := object.DiffTree(parentTree, tree)
757		if err != nil {
758			return false
759		}
760		for _, change := range changes {
761			if wanted[change.To.Name] || wanted[change.From.Name] {
762				return true
763			}
764		}
765		return false
766	}
