23	// stampedTrailer returns the first checkpoint trailer in message that
24	// prepare-commit-msg stamped itself, skipping trailers inherited from
25	// squashed commits: those link existing checkpoints and never stand in for a
26	// fresh one. A checkpoint deleted from this clone never counts either: an ID
27	// left in the message (an indented squash message, prose) would otherwise
28	// suppress the fresh trailer new work needs.
29	func stampedTrailer(ctx context.Context, message string, inherited []id.CheckpointID) (id.CheckpointID, bool) {
30		skip := make(map[id.CheckpointID]bool, len(inherited))
31		for _, cpID := range inherited {
32			skip[cpID] = true
33		}
34		for _, cpID := range withoutDeletedCheckpoints(ctx, trailers.ParseAllCheckpoints(message)) {
35			if !skip[cpID] {
36				return cpID, true
37			}
38		}
39		return id.EmptyCheckpointID, false
40	}
