42	// pickCondensationTarget chooses the trailer a commit's new work condenses
43	// into. A lone trailer is it. Among several, trailers that already have a
44	// checkpoint are links; the stamped one is the last without a checkpoint,
45	// since prepare appends after the inherited ones. None means the commit only
46	// links existing work.
47	func pickCondensationTarget(ids []id.CheckpointID, exists func(id.CheckpointID) bool) (id.CheckpointID, bool) {
48		if len(ids) == 1 {
49			return ids[0], true
50		}
51		for i := len(ids) - 1; i >= 0; i-- {
52			if !exists(ids[i]) {
53				return ids[i], true
54			}
55		}
56		return id.EmptyCheckpointID, false
57	}
