59	func pickCondensationTargetState(ids []id.CheckpointID, exists func(id.CheckpointID) bool) (target id.CheckpointID, preexisting, found bool) {
60		if len(ids) == 0 {
61			return id.EmptyCheckpointID, false, false
62		}
63		if len(ids) == 1 {
64			return ids[0], exists(ids[0]), true
65		}
66		target, found = pickCondensationTarget(ids, exists)
67		if !found {
68			// Every trailer already has a checkpoint: an amend of a squash whose
69			// inherited-trailer marker the first post-commit consumed. The stamp is
70			// the last trailer; as a preexisting target, only the session amending
71			// it (its LastCheckpointID) may write there, exactly as for a lone one.
72			return ids[len(ids)-1], true, true
73		}
74		// Recheck after selection: another session may have created the checkpoint
75		// between the first store read and condensation.
76		return target, exists(target), true
77	}
