79	// condensationTarget picks the trailer this commit condenses into and reports
80	// whether that checkpoint already existed before this post-commit began. Read
81	// once per commit: sessions condensing into the same fresh checkpoint later in
82	// this hook must not look like writes into someone else's.
83	func (s *ManualCommitStrategy) condensationTarget(ctx context.Context, repo *git.Repository, ids []id.CheckpointID) (target id.CheckpointID, preexisting, found bool) {
84		if len(ids) == 0 {
85			return id.EmptyCheckpointID, false, false
86		}
87		store, err := s.getPersistentStore(ctx, repo)
88		if err != nil {
89			// Nothing can be told apart without a store; the last trailer is
90			// where prepare stamps.
91			return ids[len(ids)-1], false, true
92		}
93		exists := func(cpID id.CheckpointID) bool { return checkpointExists(ctx, store, cpID) }
94		target, preexisting, ok := pickCondensationTargetState(ids, exists)
95		return target, preexisting, ok
96	}
