199	// prepare-commit-msg stamped, leaving out the ones it recorded as inherited
200	// and any checkpoint deleted from this clone: post-commit must never condense
201	// new work into a deleted ID, which would re-create it. It also returns the
202	// committed paths a redo's inherited checkpoints hold.
203	func stampedTrailersOf(ctx context.Context, commit *object.Commit) ([]id.CheckpointID, map[string]bool) {
204		var parent string
