221	// redone paths.
222	func takeInheritedMarker(ctx context.Context, parent string) (map[id.CheckpointID]bool, map[string]bool) {
223		root, err := perWorktreeGitRoot(ctx)
224		if err != nil {
225			return nil, nil
226		}
227		data, err := osroot.ReadFileNoFollow(root, inheritedTrailersFile)
228		if err != nil {
229			return nil, nil
230		}
231		_ = osroot.RemoveNoSymlinks(root, inheritedTrailersFile) //nolint:errcheck // a stale marker is ignored by its parent check
232		var marker inheritedTrailers
233		if json.Unmarshal(data, &marker) != nil || !slices.Contains(marker.Parents, parent) {
234			return nil, nil
235		}
236		out := make(map[id.CheckpointID]bool, len(marker.IDs))
237		for _, cpID := range marker.IDs {
238			out[cpID] = true
239		}
240		var redone map[string]bool
241		for _, p := range marker.Redone {
242			if redone == nil {
243				redone = make(map[string]bool, len(marker.Redone))
244			}
245			redone[p] = true
246		}
247		return out, redone
248	}
